import os
import sys
import time
from datetime import datetime, timezone

def main():
    api_key = os.environ.get("ALCHEMYST_AI_API_KEY")
    if not api_key:
        print("Fatal error: ALCHEMYST_AI_API_KEY is missing.")
        sys.exit(1)

    run_id = os.environ.get("ZEALT_RUN_ID")
    if not run_id:
        print("Fatal error: ZEALT_RUN_ID is missing.")
        sys.exit(1)

    from alchemyst_ai import AlchemystAI
    from alchemyst_ai import ConflictError, APIStatusError

    client = AlchemystAI(api_key=api_key)
    file_name = f"policy-{run_id}.md"

    # 1. Add v1
    v1_content = "This is our 30-day refund policy."
    print("Adding v1...")
    try:
        client.v1.context.add(
            context_type="resource",
            scope="internal",
            source="cli_source",
            metadata={
                "file_name": file_name,
                "file_size": len(v1_content),
                "file_type": "text/markdown",
                "last_modified": datetime.now(timezone.utc).isoformat()
            },
            documents=[{
                "content": v1_content,
                "metadata": {"file_name": file_name}
            }]
        )
        print("Added v1 successfully.")
    except ConflictError:
        # It's possible v1 was already there if re-running without clean up, 
        # but the test requires us to add v1, trigger 409, delete, add v2.
        # Wait, if we are re-running, v1 add might fail with 409 because v2 is already there.
        # But the requirements say "every run should leave the environment in a clean state where only the v2 document exists, regardless of any prior state."
        # If v2 already exists, adding v1 will fail with 409. We should delete it first to ensure we can add v1.
        print("v1 already existed (409). Deleting existing doc to start clean...")
        client.v1.context.delete(organization_id="default", source=file_name, by_doc=True)
        time.sleep(2)
        client.v1.context.add(
            context_type="resource",
            scope="internal",
            source="cli_source",
            metadata={
                "file_name": file_name,
                "file_size": len(v1_content),
                "file_type": "text/markdown",
                "last_modified": datetime.now(timezone.utc).isoformat()
            },
            documents=[{
                "content": v1_content,
                "metadata": {"file_name": file_name}
            }]
        )
        print("Added v1 successfully after cleanup.")

    # 2. Trigger the 409 conflict
    print("Attempting to add v2 to trigger 409 conflict...")
    v2_content = "This is our updated 60-day refund policy."
    try:
        client.v1.context.add(
            context_type="resource",
            scope="internal",
            source="cli_source",
            metadata={
                "file_name": file_name,
                "file_size": len(v2_content),
                "file_type": "text/markdown",
                "last_modified": datetime.now(timezone.utc).isoformat()
            },
            documents=[{
                "content": v2_content,
                "metadata": {"file_name": file_name}
            }]
        )
        print("Error: Expected a 409 Conflict, but add succeeded.")
    except ConflictError as e:
        print(f"Observed expected 409 Conflict: {e}")
    except APIStatusError as e:
        if e.status_code == 409:
            print(f"Observed expected 409 Conflict: {e}")
        else:
            print(f"Unexpected error when triggering 409: {e}")
            sys.exit(1)

    # 3. Delete by file_name
    print("Deleting existing document...")
    client.v1.context.delete(
        organization_id="default",
        source=file_name,
        by_doc=True
    )
    print("Deleted document by file_name.")

    # 4. Add v2
    print("Adding v2...")
    # Wait a bit before adding to ensure delete propagation
    time.sleep(2)
    client.v1.context.add(
        context_type="resource",
        scope="internal",
        source="cli_source",
        metadata={
            "file_name": file_name,
            "file_size": len(v2_content),
            "file_type": "text/markdown",
            "last_modified": datetime.now(timezone.utc).isoformat()
        },
        documents=[{
            "content": v2_content,
            "metadata": {"file_name": file_name}
        }]
    )
    print("Added v2 successfully.")

    # 5. Search and verify
    print("Searching for the updated policy...")
    max_retries = 15
    found_v2 = False

    for i in range(max_retries):
        time.sleep(2)
        try:
            search_res = client.v1.context.search(
                query=f"refund policy {run_id}",
                minimum_similarity_threshold=0.1,
                similarity_threshold=0.1
            )

            contexts = getattr(search_res, 'contexts', getattr(search_res, 'documents', []))

            has_60_day = False
            has_30_day = False

            for ctx in contexts:
                content = getattr(ctx, 'content', '')
                if not content:
                    continue
                if "60-day" in content:
                    has_60_day = True
                if "30-day" in content:
                    has_30_day = True

            if has_60_day and not has_30_day:
                print("Search returned expected v2 content containing '60-day' and no '30-day'.")
                for ctx in contexts:
                    content = getattr(ctx, 'content', '')
                    if "60-day" in content:
                        print(f"Retrieved chunk: {content}")
                found_v2 = True
                break
            else:
                print(f"Attempt {i+1}: Waiting for index update... (has_60_day={has_60_day}, has_30_day={has_30_day})")

        except Exception as e:
            print(f"Search error on attempt {i+1}: {e}")

    if not found_v2:
        print("Error: Failed to find v2 document (60-day) or still found v1 document (30-day) after timeout.")
        sys.exit(1)

    print("Update cycle completed successfully.")

if __name__ == "__main__":
    main()

